import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = list(map(int, itertools.islice(it, n)))

        unique_values = set(a)

        if len(unique_values) == 1:
            # All elements are the same, can't pair them
            print(n)
        else:
            # At least two different values, can keep pairing
            if n % 2 == 0:
                print(0)
            else:
                print(1)

if __name__ == "__main__":
    solve()
"}

