def can_form(v, cnt1, cnt2, x, y):
    # Check if we can form the presents with numbers up to v
    if cnt1 > v - v // x:
        return False
    if cnt2 > v - v // y:
        return False
    if cnt1 + cnt2 > v - v // (x * y):
        return False
    return True

# Binary search for minimum v
left, right = 1, 10**15  # Use a sufficiently large upper bound
while left < right:
    mid = (left + right) // 2
    if can_form(mid, cnt1, cnt2, x, y):
        right = mid
    else:
        left = mid + 1

print(left)

# Read input
import sys
line = sys.stdin.read().strip()
cnt1, cnt2, x, y = map(int, line.split())
"}

