import sys

s = sys.stdin.readline().strip()

def is_palindrome(s):
    return s == s[::-1]

n = len(s)

good_even = 0
good_odd = 0

# Check all substrings of the original string
for i in range(n):
    for j in range(i, n):
        substr = s[i:j+1]
        # Collapse consecutive equal characters
        collapsed = []
        for ch in substr:
            if collapsed and collapsed[-1] == ch:
                continue
            collapsed.append(ch)
        collapsed = ''.join(collapsed)
        if is_palindrome(collapsed):
            if (j - i + 1) % 2 == 0:
                good_even += 1
            else:
                good_odd += 1

print(good_even, good_odd)
"}

