import sys
import bisect

def compute_lnds_length(arr):
    """Longest non-decreasing subsequence length (O(n log n))"""
    tails = []
    for num in arr:
        idx = bisect.bisect_right(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num
    return len(tails)

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    m = int(data[1])
    species = []
    for i in range(n):
        idx = 2 + 2 * i
        s = int(data[idx])
        species.append(s)

    lnds_length = compute_lnds_length(species)
    print(n - lnds_length)

