import math

def solve():
    a, b = map(int, input().split())

    # Compute GCD and LCM
    gcd_val = math.gcd(a, b)
    lcm_val = a * b // gcd_val

    # Generate all event times (train departures) in [0, lcm_val]
    events = set()
    for k in range(lcm_val // a + 1):
        events.add(k * a)
    for k in range(lcm_val // b + 1):
        events.add(k * b)

    # Convert to sorted list
    events = sorted(events)

    prev_time = 0
    count = {'Dasha': 0, 'Masha': 0}

    for curr_time in events:
        if curr_time == prev_time:
            continue

        length = curr_time - prev_time

        if curr_time % a == 0 and curr_time % b == 0:
            # Tie at this time
            if a < b:
                # Dasha's trains more frequent, go to Masha
                count['Masha'] += length
            else:  # a > b
                count['Dasha'] += length
        elif curr_time % a == 0:
            count['Dasha'] += length
        else:  # curr_time % b == 0
            count['Masha'] += length

        prev_time = curr_time

    # Determine result
    if count['Dasha'] > count['Masha']:
        print("Dasha")
    elif count['Masha'] > count['Dasha']:
        print("Masha")
    else:
        print("Equal")

solve()
