def count_not_divisible_by_any(n):
    # Count numbers from 1 to n that are not divisible by any number from 2 to 10

    # We'll use inclusion-exclusion principle on the set {2,3,4,5,6,7,8,9,10}

    divisors = [2, 3, 4, 5, 6, 7, 8, 9, 10]
    count = 0

    for i in range(1, 1 << len(divisors)):
        mask = i
        lcm = 1

        # Calculate LCM of selected divisors
        for j in range(len(divisors)):
            if mask & (1 << j):
                lcm = lcm * divisors[j] // math.gcd(lcm, divisors[j])

        # Count numbers divisible by LCM
        count += n // lcm

    # Use inclusion-exclusion correctly: add odd-sized sets, subtract even-sized sets
    for i in range(1, 1 << len(divisors)):
        mask = i
        lcm = 1

        for j in range(len(divisors)):
            if mask & (1 << j):
                lcm = lcm * divisors[j] // math.gcd(lcm, divisors[j])

        cnt = bin(mask).count('1')
        if cnt % 2 == 1:
            continue
        else:
            count -= n // lcm

    return n - count

