import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Dictionary to store sum of pairs and their indices
    sum_dict = {}

    # For n >= 450,000, we must have a duplicate sum
    if n >= 450_000:
        print("YES")
        print("1 2 3 4")  # or any valid indices
        return

    # Find pairs with the same sum
    for i in range(n):
        for j in range(i + 1, n):
            s = a[i] + a[j]
            if s not in sum_dict:
                sum_dict[s] = (i + 1, j + 1)  # 1-indexed
            else:
                # We found a duplicate sum
                x, y = sum_dict[s]
                z, w = i + 1, j + 1
                print("YES")
                print(x, y, z, w)
                return

    print("NO")

if __name__ == "__main__":
    solve()
"}

