{"code": "
t = int(input())
for _ in range(t):
    s = input().strip()
    count = {}
    for ch in s:
        count[ch] = count.get(ch, 0) + 1

    # A character appears in s if it was pressed (either working or malfunctioning)
    # We need to determine which characters must have been working

    # If a character appears odd number of times, it must have been working
    # Because if all other buttons were malfunctioning, each would add 2 occurrences
    # So each character would appear an even number of times
    # Therefore, an odd count means at least one button must be working
    # (specifically, this character's button)

    result = []
    for ch in sorted(count.keys()):
        if count[ch] % 2 == 1:
            result.append(ch)

