    k1, k2, k3 = map(int, input().split())

    # Try all combinations of x1, x2, x3 from 0 to max_k * 2
    max_k = max(k1, k2, k3)

    # Try all combinations of x1, x2, x3 in a reasonable range
    # Actually, let's think about the problem differently: we need coverage for all t >= T
    # where T = max(x1, x2, x3)

    # For a garland with period k, if we want coverage starting at time t, we need:
    # - x_i <= t
    # - And for all times >= t, either x_i <= time and (time - x_i) % k == 0

    # This means that if we have a garland with period k, it covers times: x, x+k, x+2k, ...
    # So starting from x, it covers at least one time out of every k consecutive seconds

    # To cover all seconds from some T onward, we need the union of the coverage sets
    # to form a complete set

    # Actually, let's just try all combinations of x1, x2, x3 in a range
    # from 0 to max_k * 2

    found = False

    for x1 in range(max_k * 2):
