import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n, k = int(data[idx]), int(data[idx+1])
    idx += 2

    a = list(map(int, data[idx:idx+n]))
    idx += n

    t = list(map(int, data[idx:idx+n]))

    # Calculate sum of a for all minutes where Mishka is already awake
    awake_total = 0
    for i in range(n):
        if t[i] == 1:
            awake_total += a[i]

    # We want to find a window of length k that maximizes the sum of a[i] where t[i] == 0
    # These are the asleep minutes we can cover with the technique

    # Slide window over the a array, only adding asleep minutes
    window_sum = 0
    for i in range(k):
        if t[i] == 0:
            window_sum += a[i]

    max_gain = window_sum

    for i in range(k, n):
        # Remove element leaving the window, add element entering
        if t[i - k] == 0:
            window_sum -= a[i - k]
        if t[i] == 0:
            window_sum += a[i]

        max_gain = max(max_gain, window_sum)

    print(awake_total + max_gain)

if __name__ == "__main__":
    main()
