    # Try different numbers of summands k
    for k in range(1, n + 1):
        # Check if we can represent n as sum of k p-binary numbers
        if p >= 0:
            # p is non-negative, need at least k * p <= n
            if k * p > n:
                continue
            S = n - k * p
            # Can we represent S as sum of k powers of 2?
            # One approach: use binary representation and check if we can split into k terms
            # Each power of 2 is a bit in binary representation
            # If we have S binary representation with m bits, can we split into k terms?
            # Actually, we need to use k powers of 2 (can repeat)
            # We need k terms to sum to S
            # We can use 2^0 as many times as needed

            # If we use x copies of 2^0, we can reduce the problem to S' = S - x, and k' = k - x
            # With k' terms and powers >= 1

            # Try using all 2^0s first
            if S >= k:
                # Use k terms of 2^0 to get sum k, need remaining S - k
                if (S - k) % 2 == 0:
                    # Use 2^1 repeatedly to get the remaining
                    return k

        else:
            # p is negative, can be more flexible
            if k * p > n:
                continue
            S = n - k * p
            if S >= 0:
                # Try using all 2^0s first
                if S >= k:
                    if (S - k) % 2 == 0:
                        return k

