import sys

def solve():
    a, b = map(int, sys.stdin.readline().split())

    # Tie-breaker: a > b => Dasha; else Masha
    if a > b:
        tie_direction = 'Dasha'
    else:
        tie_direction = 'Masha'

    L = a * b // (a % b) if a % b else a  # LCM

    current_dasha = a
    current_masha = b
    time = 0
    dasha_len = 0
    masha_len = 0

    while time < L:
        if current_dasha <= current_masha:
            next_event = current_dasha
            direction = 'Dasha' if (current_dasha != current_masha) else tie_direction
            duration = next_event - time
            if direction == 'Dasha':
                dasha_len += duration
            else:
                masha_len += duration
            time = next_event
            current_dasha += a
        else:
            next_event = current_masha
            direction = 'Masha' if (current_dasha != current_masha) else tie_direction
            duration = next_event - time
            if direction == 'Dasha':
                dasha_len += duration
            else:
                masha_len += duration
            time = next_event
            current_masha += b

    if dasha_len > masha_len:
        print('Dasha')
    elif masha_len > dasha_len:
        print('Masha')
    else:
        print('Equal')

if __name__ == '__main__':
    solve()
