def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Count frequency of each element
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Sort elements
    sorted_a = sorted(a)

    # Try to assign elements to sequences
    inc = []  # Strictly increasing sequence
    dec = []  # Strictly decreasing sequence

    # First pass: assign elements to increasing or decreasing
    for num in sorted_a:
        count = freq[num]

        # If this is the first occurrence, decide which sequence to put it in
        if count > 1:
            # Need to have at least one element > num if we put it in increasing
            # Need to have at least one element < num if we put it in decreasing
            # We'll try increasing first

            # Check if we can put it in increasing
            if inc and inc[-1] < num:
                inc.append(num)
                count -= 1
            elif dec and dec[-1] > num:
                dec.append(num)
                count -= 1
            else:
                # Can't put it in either sequence - contradiction
                print("NO")
                return
        else:
            # Single occurrence, can put in either
            if inc and inc[-1] < num:
                inc.append(num)
            elif dec and dec[-1] > num:
                dec.append(num)

    # Check if all elements are used
    if len(inc) + len(dec) != n:
        print("NO")
        return

    # Print result
    print("YES")
    print(len(inc))
    if inc:
        print(" ".join(map(str, inc)))
    else:
        print()

    print(len(dec))
    if dec:
        print(" ".join(map(str, dec)))
    else:
        print()

