def count_bits(x):
    """Count the number of bits set in binary representation"""
    return bin(x).count('1')

# We need at most n summands (worst case: n=1, p=0, we might need 1 summand)
for k in range(1, n + 1):
    target = n - k * p
    bits_set = count_bits(target)
    # We need exactly k bits set (since we need k distinct powers of 2)
    if bits_set == k:
        print(k)
        exit()

