def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # We can always reduce the array if we can find at least one increasing pair
        # because we can always remove elements from increasing pairs

        # Let's greedily remove the larger element in increasing pairs
        # or remove the smaller element if it's at the end

        # Create a copy of the array
        arr = a[:]

        # Always try to find and remove from increasing pairs
        for i in range(n - 1):
            if arr[i] < arr[i + 1]:
                # Remove the larger element (arr[i+1])
                del arr[i + 1]
                n -= 1

        # Check if we can continue removing
        while n > 1:
            found = False
            for i in range(n - 1):
                if arr[i] < arr[i + 1]:
                    found = True
                    break

            if not found:
                # We got stuck, cannot reduce to length 1
                print("NO")
                break

            # Remove from the rightmost increasing pair (or left if at end)
            for i in range(n - 1):
                if arr[i] < arr[i + 1]:
                    del arr[i + 1]
                    n -= 1
                    break
        else:
            # Successfully reduced to length 1
            print("YES")

