    return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

def point_inside_triangle(p, t1, t2, t3):
    """Check if point p is inside triangle (t1, t2, t3)
    Returns True if point is inside or on the boundary"""
    c1 = cross(t1, t2, p)
    c2 = cross(t2, t3, p)
    c3 = cross(t3, t1, p)

    if (c1 >= 0 and c2 >= 0 and c3 >= 0) or (c1 <= 0 and c2 <= 0 and c3 <= 0):
        return True
    return False

def segment_inside_triangle(s1, s2, t1, t2, t3):
    """Check if segment (s1, s2) lies entirely within triangle (t1, t2, t3)
    - Both endpoints must be inside the triangle (including boundary)
    - The segment should be fully contained, not just intersecting
    - The segment may be collinear with a triangle edge
    """
    # Check if both endpoints are inside the triangle (including boundary)
    if not point_inside_triangle(s1, t1, t2, t3):
        return False
    if not point_inside_triangle(s2, t1, t2, t3):
        return False

    # Check if segment is collinear with any triangle edge
    collinear = False
    for (v1, v2) in [(t1, t2), (t2, t3), (t3, t1)]:
        if cross(v1, v2, s1) == 0 and cross(v1, v2, s2) == 0:
            collinear = True
            break

    if collinear:
        # Check if the segment s is a subset of the triangle edge
        for (v1, v2) in [(t1, t2), (t2, t3), (t3, t1)]:
            if cross(v1, v2, s1) == 0 and cross(v1, v2, s2) == 0:
                # Check if the segment s lies between v1 and v2
                # s1 and s2 should be between v1 and v2
                def between(p, p1, p2):
                    return (point_inside_triangle(p, p1, p2, v1) and point_inside_triangle(p, p1, p2, v2) or
                            point_inside_triangle(p, p1, p2, v1) and point_inside_triangle(p, p1, p2, v2))

                if not between(s1, v1, v2):
                    return False
                if not between(s2, v1, v2):
                    return False

                # Check if any triangle vertex lies exactly on the segment
                for v in [v1, v2]:
                    if cross(s1, s2, v) == 0:
                        return False
                return True
    else:
        # For non-collinear segments, check if they lie within the triangle
        # A segment lies within a triangle if it doesn't intersect any edge
        for (v1, v2) in [(t1, t2), (t2, t3), (t3, t1)]:
            # Calculate the intersection of the segment s1-s2 with the triangle edge v1-v2
            def intersect(p1, p2, p3, p4):
                # Check if line segments (p1,p2) and (p3,p4) intersect
                # Returns True if they intersect (including collinear but overlapping)

                # Check if the lines intersect
                c1 = cross(p1, p2, p3)
                c2 = cross(p1, p2, p4)
                c3 = cross(p3, p4, p1)
                c4 = cross(p3, p4, p2)

                if ((c1 >= 0 and c2 <= 0) or (c1 <= 0 and c2 >= 0)) and ((c3 >= 0 and c4 <= 0) or (c3 <= 0 and c4 >= 0)):
                    return True

                # Check if any endpoints lie on the other segment
                if cross(p1, p2, p3) == 0 and cross(p1, p2, p4) == 0:
                    return True
                if cross(p3, p4, p1) == 0 and cross(p3, p4, p2) == 0:
                    return True

                return False

            if intersect(s1, s2, v1, v2):
                return False
        return True

def is_edge_covered(s, edges, triangles):
    """Check if edge s is fully covered by any triangle"""
    for tri in triangles:
        if tri != s:
            # Check if the segment s lies entirely inside triangle tri
            if segment_inside_triangle(s[0], s[1], tri[0], tri[1], tri[2]):
                return True
    return False

def solve():
