        p1 = (coords[0], coords[1])
        p2 = (coords[2], coords[3])
        p3 = (coords[4], coords[5])
        triangles.append((p1, p2, p3))

    # Calculate total perimeter of all triangles
    total_perimeter = 0

    for i in range(n):
