            p1 = triangles[i][j]
            p2 = triangles[i][(j + 1) % 3]
            edge = (p1, p2)
            length = distance(p1, p2)
            if not is_edge_covered(edge, triangles, triangles):
                total_perimeter += length

    print(total_perimeter)

