{"code": "def is_lake(map, i, j, n, m):
    if map[i][j] != '.':
        return False
    visited = [[False] * m for _ in range(n)]
    stack = [(i, j)]
    visited[i][j] = True

    # Check if this region touches the border
    touches_border = False
    if i == 0 or i == n-1 or j == 0 or j == m-1:
        touches_border = True

    while stack:
        x, y = stack.pop()
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and map[nx][ny] == '.':
                visited[nx][ny] = True
                if nx == 0 or nx == n-1 or ny == 0 or ny == m-1:
                    touches_border = True
                stack.append((nx, ny))

    return not touches_border

def solve():
    n, m, k = map(int, input().split())
    grid = [list(input().strip()) for _ in range(n)]

    # Identify lakes
    lakes = []
    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # BFS to find connected region
                q = [(i, j)]
                visited[i][j] = True
                region = []
                touches_border = False
                if i == 0 or i == n-1 or j == 0 or j == m-1:
                    touches_border = True

                while q:
                    x, y = q.pop(0)
                    region.append((x, y))
                    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                            visited[nx][ny] = True
                            if nx == 0 or nx == n-1 or ny == 0 or ny == m-1:
                                touches_border = True
                            q.append((nx, ny))

                if not touches_border:
                    lakes.append(region)

    # Sort lakes by size (smallest to largest)
    lakes.sort(key=len)

    # We need to remove lakes[0..len(lakes)-1-k] lakes
    # Those will be filled with land
    if k > 0:
        for lake in lakes[:len(lakes)-k]:
            for x, y in lake:
                grid[x][y] = '*'

    # Print result
    print(len(lakes) - k)
    for row in grid:
        print(''.join(row))

