def min_extensions(base, target, extensions):
    if base >= target:
        return 0

    # Sort extensions in ascending order
    extensions.sort()

    # Try using 0, 1, 2, ... extensions
    for i in range(1, len(extensions) + 1):
        product = 1
        for j in range(i):
            product *= extensions[j]

        if base * product >= target:
            return i

    # If we couldn't reach the target
    return float('inf')

