config1 = min_extensions(h, a, extensions) + min_extensions(w, b, extensions)
config2 = min_extensions(h, b, extensions) + min_extensions(w, a, extensions)

# Get minimum answer
ans = min(config1, config2)

if ans == float('inf'):
    print(-1)
else:
    print(ans)
