def is_valid(word):
    if not word:
        return True

    block = []
    for c in word:
        if c in 'aeiou':
            if block:
                if len(block) >= 3 and len(set(block)) >= 2:
                    return False
                block = []
        else:
            block.append(c)

    if len(block) >= 3 and len(set(block)) >= 2:
        return False

    return True

def solve():
    s = input().strip()
    n = len(s)

    # Precompute valid segments
    valid = {}
    for i in range(n + 1):
        for j in range(i + 1, n + 1):
            segment = s[i:j]
            if is_valid(segment):
                valid[(i, j)] = True

    # DP to find minimum spaces
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            if valid.get((j, i), False):
                dp[i] = min(dp[i], dp[j] + 1)

    if dp[n] == float('inf'):
        print(s)
    else:
        # Backtrack to find positions
        i = n
        result = []
        while i > 0:
            for j in range(i):
                if dp[i] == dp[j] + 1:
                    result.append(s[j:i])
                    i = j
                    break

        result.reverse()
        print(' '.join(result))

