{"code": "
import sys

def is_palindrome(s):
    return s == s[::-1]

def solve(s):
    n = len(s)
    count_even = 0
    count_odd = 0

    # Iterate through all substrings
    for i in range(n):
        # Compressed version for substring starting at i
        compressed = []
        for j in range(i, n):
            if not compressed or compressed[-1] != s[j]:
                compressed.append(s[j])
            # Check if compressed string is a palindrome
            if is_palindrome(compressed):
                length = j - i + 1
                if length % 2 == 0:
                    count_even += 1
                else:
                    count_odd += 1

    return count_even, count_odd

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    even, odd = solve(s)
    print(even, odd)
