def solve(s):
    n = len(s)
    count_even = 0
    count_odd = 0

    # We need to find all substrings whose compressed version is a palindrome
    # For a substring to be good, its compressed version must be a palindrome

    # Let's iterate through all possible substrings and maintain the compressed version
    for i in range(n):
        compressed = []
        for j in range(i, n):
            if not compressed or compressed[-1] != s[j]:
                compressed.append(s[j])
