import sys

# For each character, we compute a parity mask
# - 1 bit per character (a-z)
# - bit i is 1 if character (i) has odd frequency

def compute_parity_mask(s):
    mask = 0
    for ch in s:
        bit = ord(ch) - ord('a')
        mask ^= (1 << bit)
    return mask

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    strings = input[1:1+n]

    # Count parity masks
    cnt = {}
    for s in strings:
        p = compute_parity_mask(s)
        cnt[p] = cnt.get(p, 0) + 1

    # Total valid pairs
    total = 0

    # Check all pairs (p1, p2)
    for p1, c1 in cnt.items():
        for p2, c2 in cnt.items():
            if p1 == p2:
                # Both strings have same parity
                # Combined parity is 0 (all even) - palindrome
                total += c1 * (c1 - 1) // 2
            else:
                # Check if p1 ^ p2 has at most one bit set
                xor = p1 ^ p2
                if bin(xor).count('1') <= 1:
                    total += c1 * c2

    print(total)

if __name__ == "__main__":
    main()
"}

