# For each character, we compute a parity mask
# - 1 bit per character (a-z)
# - bit i is 1 if character (i) has odd frequency

def compute_parity_mask(s):
    mask = 0
    for ch in s:
        bit = ord(ch) - ord('a')
        mask ^= (1 << bit)
    return mask

def main():
