def has_typo(word):
    # Check if there's a typo in any substring
    n = len(word)

    # Check windows of length 3 to 26
    for window_len in range(3, 27):
        for i in range(n - window_len + 1):
            window = word[i:i+window_len]

            # Extract consonants in this window
            consonants = []
            for c in window:
                if c not in vowels:
                    consonants.append(c)

            # If we have at least 3 consonants and they are not all the same
            if len(consonants) >= 3 and not all(c == consonants[0] for c in consonants):
                return True, i, window_len

    return False, -1, -1

def add_spaces(word):
    n = len(word)

    # Try all possible splits by inserting spaces
    # Check if we can split after each position
    for split_pos in range(1, n):
        left = word[:split_pos]
        right = word[split_pos:]

        if not has_typo(left)[0] and not has_typo(right)[0]:
            return left + ' ' + right

    # If no single split works, try multiple splits recursively
    for split_pos in range(1, n):
        left = word[:split_pos]
        right = word[split_pos:]

        # Check left half
        if not has_typo(left)[0]:
            # Recursively check right half
            right_split = add_spaces(right)
            return left + ' ' + right_split

    # If no splits work, we need to split at each typo
    splits = []
    for i in range(n):
        for j in range(i+3, n+1):
            substring = word[i:j]
            if has_typo(substring)[0]:
