    g = math.gcd(a, b)

    # Get all divisors of g
    def get_divisors(n: int) -> list[int]:
        divisors = set()
        i = 1
        while i * i <= n:
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
            i += 1
        return sorted(divisors)

    divisors = get_divisors(g)

    # Process queries
    n = int(input())
    for _ in range(n):
        low, high = map(int, input().split())
        # Find largest divisor <= high and >= low
