def solve():
    # Read input
    first_line = sys.stdin.readline().strip().split()
    n = int(first_line[0])
    m = int(first_line[1])
    k = int(first_line[2])

    grid = []
    for _ in range(n):
        line = sys.stdin.readline().strip()
        grid.append(list(line))

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find lakes (connected components of '.')
    visited = [[False] * m for _ in range(n)]
    lakes = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # Find all cells in this lake
                lake = []
                queue = deque([(i, j)])
                visited[i][j] = True

                # Check if any cell is on the border
                on_border = False

                while queue:
                    x, y = queue.popleft()
                    lake.append((x, y))

                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if not visited[nx][ny] and grid[nx][ny] == '.':
                                visited[nx][ny] = True
                                queue.append((nx, ny))
                            elif grid[nx][ny] == '*' or nx == 0 or nx == n-1 or ny == 0 or ny == m-1:
                                # Found a border or land cell
                                on_border = True

                # If the lake has no border cells, it's a true lake
                if not on_border:
                    lakes.append(lake)

    # Sort lakes by size (smallest first)
    lakes.sort(key=lambda x: len(x))

    # We need to remove (number of lakes - k) lakes
    # To remove a lake, we need to transform cells that connect it to the border
    # We'll do BFS from the border to find the minimum cells to transform

    # Output the original grid
    for row in grid:
        print(''.join(row))

    # Transform cells for removed lakes
    for i in range(len(lakes) - k):
        # BFS from the border to find cells that connect this lake to the border
        lake_cells = set(lakes[i])
        queue = deque() 
        visited = set()

        for x, y in lake_cells:
            # Check if this cell is adjacent to the border
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if nx == 0 or nx == n-1 or ny == 0 or ny == m-1:
                    # This lake connects to the border, so we need to transform cells
                    queue.append((x, y))
                    visited.add((x, y))
                    break

        # BFS to find the minimum set of cells to transform
        # We need to find the cells that form the boundary between the lake and the border
        while queue:
            x, y = queue.popleft()

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if (nx, ny) in lake_cells:
                    if nx == 0 or nx == n-1 or ny == 0 or ny == m-1:
                        # Transform this lake cell
                        if grid[nx][ny] == '.':
                            grid[nx][ny] = '*'
                    else:
                        # If this adjacent cell is in the lake, we need to transform it
                        if grid[nx][ny] == '.':
                            grid[nx][ny] = '*'
                else:
                    # If this adjacent cell is not in the lake, we need to transform it if it connects
                    # Check if this cell connects to the border or to a lake cell that we need to transform
                    is_transformed = False

                    for ddx, ddy in directions:
                        n2x, n2y = nx + ddx, ny + ddy
