        v = int(next(it))
        graph[u].append(v)
        graph[v].append(u)

    # Use BFS to find the number of vertices on each cycle
    # We'll count cycles using DFS
    is_cycle = [False] * (n + 1)  # True if vertex is on a cycle

    def dfs(u, prev, depth):
        stack = [(u, prev, 0)]
        while stack:
            node, parent, d = stack.pop()
            if is_cycle[node]:
                # Found a cycle
                count = 0
                # Count vertices on the cycle
                curr = parent
                while curr != node:
                    if is_cycle[curr]:
                        count += 1
                    curr = parent[curr]
                if is_cycle[node]:
                    count += 1
                # For each vertex on the cycle, mark it as having a cycle
                curr = parent
                while curr != node:
                    if is_cycle[curr]:
                        count += 1
                    curr = parent[curr]
                if is_cycle[node]:
                    count += 1

                return count

            if depth[node] > 0:
                stack.append((node, parent, depth[node]))
            else:
                visited[node] = True
                for neighbor in graph[node]:
                    if neighbor != parent:
                        stack.append((neighbor, node, depth[node] + 1))

    visited = [False] * (n + 1)
    dfs(1, -1, 0)

    # Now we have is_cycle array
    # Count cycle vertices on path from x to y
    def count_cycle_vertices(x, y):
        cycle_count = 0
        # Use BFS to find LCA and count cycle vertices
        depth = {x: 0}
        q = deque([x])
        parent = {}
        while q:
            node = q.popleft()
            for neighbor in graph[node]:
                if neighbor != parent.get(node, -1) and neighbor not in depth:
                    depth[neighbor] = depth[node] + 1
                    parent[neighbor] = node
