        # Get sorted list of frequencies
        sorted_freq = sorted(freq.values())

        # Find the frequency with the most occurrences
        max_freq = max(sorted_freq)

        # Calculate how many pairs we can form
        # We can form pairs using the largest frequency
        pairs = 0

        # Try to pair with other frequencies
        for i in range(len(sorted_freq)):
            if i == 0:
                # Use the first frequency as base
                for j in range(1, len(sorted_freq)):
                    if sorted_freq[j] > 0:
                        pairs += 1
                        sorted_freq[j] -= 1
            else:
                # For each occurrence, we need a different number
                if sorted_freq[i] > 0:
                    # Find another frequency to pair with
                    for j in range(1, len(sorted_freq)):
                        if sorted_freq[j] > 0 and j != i:
                            pairs += 1
                            sorted_freq[j] -= 1
                            break

        print(n - 2 * pairs)

