    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Count occurrences
        freq = {}
        for num in a:
            freq[num] = freq.get(num, 0) + 1

        # Convert to multiset
        freq_list = sorted(freq.values())

        # Find the maximum number of pairs
        pairs = 0

        # Greedy algorithm: take from the smallest frequency
        while freq_list:
            # Find the smallest non-zero frequency
            min_idx = -1
            for i in range(len(freq_list)):
                if freq_list[i] > 0:
                    min_idx = i
                    break

            if min_idx == -1:
                break

            # Find a partner (not the same frequency)
            partner_idx = -1
            for i in range(len(freq_list)):
                if i != min_idx and freq_list[i] > 0:
                    partner_idx = i
                    break

            if partner_idx != -1:
                pairs += 1
                freq_list[min_idx] -= 1
                freq_list[partner_idx] -= 1
            else:
                break

        print(n - 2 * pairs)

solve()
