import sys

def count_good(v, x, y):
    # Total numbers NOT divisible by x OR y
    # = v - numbers divisible by both x and y (since x and y are distinct primes)
    return v - (v // (x * y))

def solve(cnt1, cnt2, x, y):
    target = cnt1 + cnt2

    # Binary search bounds
    low = 1
    high = 1000000000  # Upper bound

    while low < high:
        mid = (low + high) // 2

        if count_good(mid, x, y) >= target:
            high = mid
        else:
            low = mid + 1

    return low

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit()

    cnt1, cnt2, x, y = map(int, data)

    result = solve(cnt1, cnt2, x, y)

    print(result)
"}

