def min_extensions(a, b, h, w, n, extensions):
    # Check if already possible
    if h >= a and w >= b:
        return 0
    if h >= b and w >= a:
        return 0

    # DP: dp[i] = minimum product we can achieve using exactly i extensions
    # We'll try all possible numbers of extensions from 0 to n
    for k in range(0, n + 1):
        # Try all ways to split k extensions between the two dimensions
        # Try using i extensions on h and (k - i) extensions on w
        # For each i from 0 to k
        for i in range(0, k + 1):
            # Try all combinations of extensions
            for used_h in combinations(extensions, i):
                used_h_product = 1
                for x in used_h:
                    used_h_product *= x
                needed_w_product = max(a // h + 1, 1) if i == k else max(b // h + 1, 1)
                needed_w_product = max(needed_w_product, 1)

                # Need to use k - i extensions on w
                remaining_ext = [x for x in extensions if x not in used_h]
                for used_w in combinations(remaining_ext, k - i):
                    used_w_product = 1
                    for x in used_w:
                        used_w_product *= x

                    # Check orientation 1: a×b on h×w
                    if h * used_h_product >= a and w * used_w_product >= b:
                        return k

                    # Check orientation 2: a×b on w×h
                    if h * used_h_product >= b and w * used_w_product >= a:
                        return k

    return -1

