    for i in range(1, n - 1):
        for j in range(1, m - 1):
            if grid[i][j] == '.' and not visited[i][j]:
                # This is a potential lake
                # Do BFS to check if it's connected to the border
                queue = [(i, j)]
                visited[i][j] = True
                area = 0
                border_reached = False

                while queue:
                    r, c = queue.pop(0)
                    area += 1

                    # Check if this cell is on the border
                    if r == 0 or r == n - 1 or c == 0 or c == m - 1:
                        border_reached = True

                    # Add neighbors
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc] == '.':
