import math

def distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2)**2 + (y1 - y2)**2)

def point_inside_triangle(p, a, b, c):
    """Check if point p is inside triangle abc using barycentric coordinates"""
    d = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    if d == 0:
        return False  # colinear, not a triangle

    d1 = (p[0] - a[0]) * (c[1] - a[1]) - (p[1] - a[1]) * (c[0] - a[0])
    d2 = (p[0] - b[0]) * (a[1] - b[1]) - (p[1] - b[1]) * (a[0] - b[0])
    d3 = (p[0] - c[0]) * (b[1] - c[1]) - (p[1] - c[1]) * (b[0] - c[0])

    if d1 >= 0 and d2 >= 0 and d3 >= 0:
        return True
    if d1 <= 0 and d2 <= 0 and d3 <= 0:
        return True
    return False

def line_segment_intersection(p1, p2, p3, p4):
    """Check if segments p1p2 and p3p4 intersect"""
    def orientation(p, q, r):
        val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
        if val == 0:
            return 0  # colinear
        return 1 if val > 0 else 2  # clock or counterclock wise

    o1 = orientation(p1, p2, p3)
    o2 = orientation(p1, p2, p4)
    o3 = orientation(p3, p4, p1)
    o4 = orientation(p3, p4, p2)

    # General case
    if o1 != o2 and o3 != o4:
        return True

    # Special Cases
    # p3 on p1p2
    if o1 == 0 and on_segment(p1, p3, p2):
        return True

    # p4 on p1p2
    if o2 == 0 and on_segment(p1, p4, p2):
        return True

    # p1 on p3p4
    if o3 == 0 and on_segment(p3, p1, p4):
        return True

    # p2 on p3p4
    if o4 == 0 and on_segment(p3, p2, p4):
        return True

    return False

def on_segment(p, q, r):
    """Check if point q lies on line segment pr"""
    if min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and min(p[1], r[1]) <= q[1] <= max(p[1], r[1]):
        return True
    return False

n = int(input())
triangles = []

for _ in range(n):
    x1, y1, x2, y2, x3, y3 = map(int, input().split())
    triangles.append([(x1, y1), (x2, y2), (x3, y3)])

total_perimeter = 0
edge_lengths = {}

# Add all edges with their lengths
for i, triangle in enumerate(triangles):
    a = triangle[0]
    b = triangle[1]
    c = triangle[2]

    d1 = distance(a[0], a[1], b[0], b[1])
    d2 = distance(b[0], b[1], c[0], c[1])
    d3 = distance(c[0], c[1], a[0], a[1])

    total_perimeter += d1 + d2 + d3

    edge_lengths[(i, 0)] = d1  # edge from a to b
    edge_lengths[(i, 1)] = d2  # edge from b to c
    edge_lengths[(i, 2)] = d3  # edge from c to a

# Check overlaps between all pairs of edges
for i, triangle1 in enumerate(triangles):
    for j, triangle2 in enumerate(triangles):
        if i == j:
            continue

        for e1 in range(3):
            for e2 in range(3):
                p1 = triangle1[e1 % 3]
                p2 = triangle1[(e1+1) % 3]
                q1 = triangle2[e2 % 3]
                q2 = triangle2[(e2+1) % 3]

                if line_segment_intersection(p1, p2, q1, q2):
                    # Check if the entire edge is inside the other triangle
                    # Get the midpoint of the edge
                    mid = ((p1[0] + p2[0])/2, (p1[1] + p2[1])/2)

                    if point_inside_triangle(mid, triangle2[0], triangle2[1], triangle2[2]):
                        # Entire edge is inside the other triangle
                        overlap_length = edge_lengths.get((i, e1), 0)
                        total_perimeter -= overlap_length

