    """Determine if first player wins.
    """
    # Manhattan distance between chips
    def distance(a_x, a_y, b_x, b_y):
        return abs(a_x - b_x) + abs(a_y - b_y)

    # Check if both chips are stuck
    def is_stuck(x1, y1, x2, y2, blocked):
        # Check if either chip can move
        if (x1 > 1 or x1 < n) and (x1, y1) not in blocked:
            return False
        if (x2 > 1 or x2 < n) and (x2, y2) not in blocked:
            return False
        return True

    # Check if first player can win from this state
    def can_win(x1, y1, x2, y2, blocked):
        # If chips are already together
        if distance(x1, y1, x2, y2) == 0:
            return True

        # If first player can make a move that leads to a win
        for (dx, dy) in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_x1, new_y1 = x1 + dx, y1 + dy
            if 1 <= new_x1 <= n and 1 <= new_y1 <= m:
                # First player moves first chip
                if (new_x1, new_y1) not in blocked and distance(new_x1, new_y1, x2, y2) < distance(x1, y1, x2, y2):
                    # Check if first player wins immediately
                    if distance(new_x1, new_y1, x2, y2) == 0:
                        return True

                    # Check if second player can block
                    can_second_win = False
                    for block_x, block_y in [(i, j) for i in range(1, n+1) for j in range(1, m+1) if (i, j) not in blocked and (i, j) != (new_x1, new_y1) and (i, j) != (x2, y2)]:
                        if (x2, y2) not in blocked and distance(x2, y2, new_x1, new_y1) < distance(x1, y1, x2, y2) and distance(new_x1, new_y1, x2, y2) > distance(x1, y1, x2, y2):
                            # If second player can block optimally, check if it leads to a win
                            if can_win(new_x1, new_y1, x2, y2, blocked | {(block_x, block_y)}):
                                can_second_win = True
                                break

                    if not can_second_win:
                        return True

            # Check if first player moves second chip
            new_x2, new_y2 = x2 + dx, y2 + dy
            if 1 <= new_x2 <= n and 1 <= new_y2 <= m:
                if (new_x2, new_y2) not in blocked and distance(x1, y1, new_x2, new_y2) < distance(x1, y1, x2, y2):
                    if distance(x1, y1, new_x2, new_y2) == 0:
                        return True

                    can_second_win = False
                    for block_x, block_y in [(i, j) for i in range(1, n+1) for j in range(1, m+1) if (i, j) not in blocked and (i, j) != (x1, y1) and (i, j) != (new_x2, new_y2)]:
                        if (x1, y1) not in blocked and distance(x1, y1, new_x2, new_y2) < distance(x1, y1, x2, y2) and distance(x1, y1, new_x2, new_y2) > distance(x1, y1, x2, y2):
                            if can_win(x1, y1, new_x2, new_y2, blocked | {(block_x, block_y)}):
                                can_second_win = True
                                break

                    if not can_second_win:
                        return True

        # If first player can't win
        return False

    return 'First' if can_win(x1, y1, x2, y2, set()) else 'Second'

