w = input().strip()
letter = input().strip().lower()

# Find all positions that need to be replaced
positions = set()
for i in range(len(w)):
    # Check all substrings starting at i
    for j in range(i, len(w)):
        substr = w[i:j+1]
        for f in forbidden:
            if substr.lower() == f.lower():
                positions.add(i)
                break  # Found a forbidden substring at position i
        if i in positions:
            break
    if i in positions:
        break

# Now construct the result
result = []
for i, char in enumerate(w):
    if i in positions:
        # Try to replace with lucky letter
        if char.lower() != letter:
            result.append(letter)
        else:
            # Already lucky letter, we need to replace with smallest possible character
            # Choose smallest character, which is 'a' if lowercase, 'A' if uppercase
            if char.islower():
                result.append('a')
            else:
                result.append('A')
    else:
        result.append(char)

print(''.join(result))
