import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    ptr = 0
    n = int(data[ptr]); ptr += 1
    p = list(map(int, data[ptr:ptr + n])); ptr += n

    t = int(data[ptr]); ptr += 1
    q = set()
    if t > 0:
        for _ in range(t):
            q.add(int(data[ptr])); ptr += 1

    # We need to pair each negative with a matching positive
    # Let's try to construct the sequence
    x = [0] * n
    stack = []

    for i in range(n):
        if i + 1 in q:
            # Negative position, need to make it negative
            x[i] = -p[i]
            stack.append(p[i])  # Record the type
        else:
            # Positive position, need to match with a negative
            # Pop from stack if available
            if stack:
                x[i] = -stack.pop()
            else:
                x[i] = p[i]
                stack.append(p[i])

    # Check if stack is empty (balanced)
    if stack:
        print("NO")
        return

    print("YES")
    print(" ".join(map(str, x)))

if __name__ == "__main__":
    solve()
"}

