def reconstruct_array(b_prime, c_prime):
    n = len(b_prime) + 1

    # Check if we can create a valid array
    # We'll need to match b' and c' with adjacent positions in a

    # We can think of this as a graph matching problem
    # where each position in b' and c' can be matched with an adjacent pair

    # We'll try to find a matching that covers all n-1 adjacent pairs

    # Let's create a list of possible edges
    edges = []
    for i in range(n - 1):
        for j in range(n - 1):
            # Position i in a corresponds to position j in b' and c'
            # Check if this is a valid assignment
            if b_prime[j] <= c_prime[j]:
                edges.append((i, j))

    # Now we need to find a matching that covers all positions
    # This is a bipartite matching problem

    # Let's implement a simple greedy approach
    used_b = [False] * len(b_prime)
    used_c = [False] * len(c_prime)
    a = [0] * n

    # We need to assign values to positions 1..n
    # Let's greedily assign values
    for i in range(1, n):
        if a[i] == 0:
            # We need to find a valid pair for position i
            for j in range(len(b_prime)):
                if not used_b[j]:
                    # Try using b_prime[j] as one of the min values
                    # and find a corresponding max value
                    for k in range(len(c_prime)):
                        if not used_c[k] and c_prime[k] >= b_prime[j]:
                            # Try assigning a[i] = c_prime[k], a[i+1] = b_prime[j]
                            if b_prime[j] <= c_prime[k]:
                                a[i] = c_prime[k]
                                a[i+1] = b_prime[j]
                                used_b[j] = True
                                used_c[k] = True
                                break

            if a[i] == 0:
                # Try the other way around
                for j in range(len(b_prime)):
                    if not used_b[j]:
                        # Try using b_prime[j] as one of the max values
                        # and find a corresponding min value
                        for k in range(len(c_prime)):
