                                # Try assigning a[i] = b_prime[j], a[i+1] = c_prime[k]
                                if c_prime[k] >= b_prime[j]:
                                    a[i] = b_prime[j]
                                    a[i+1] = c_prime[k]
                                    used_b[j] = True
                                    used_c[k] = True
                                    break


    # Check if we used all elements
    if all(used_b) and all(used_c):
        return a
    else:
        return -1

