def solve():
    n = int(input())
    contacts = []
    for _ in range(n):
        contacts.append(input().strip())
    a = list(map(int, input().split()))

    # For each employee, store the set of people who have them in their contact list
    S = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if contacts[i][j] == '1':
                S[i].append(j)

    # Backtracking function
    def backtrack(index, invited, messages):  # index: current employee, invited: set of invited employees, messages: dict of messages per employee
        if index == n:
            # Check if Igor loses
            for i in range(n):
                if i in invited:
                    received = 1 + sum(1 for j in invited if i in S[j])
                else:
                    received = sum(1 for j in invited if i in S[j])

                if received == a[i]:
                    return False  # Igor wins
            return invited  # Igor loses

        # Try not inviting index
        invite = False
        if index in invited:
            invited.remove(index)
        # messages[index] = 0
        if backtrack(index + 1, invited, messages) is not False:
            return backtrack(index + 1, invited, messages)
