    # Return True if segments intersect
    # p1, p2 = first segment
    # p3, p4 = second segment

    # Check if segments intersect using cross product
    d = (p2[0]-p1[0])*(p4[1]-p3[1]) - (p2[1]-p1[1])*(p4[0]-p3[0])
    if d == 0:
        return False  # Parallel segments

    # Check if points lie on opposite sides of the segments
    d1 = (p3[0]-p1[0])*(p4[1]-p3[1]) - (p3[1]-p1[1])*(p4[0]-p3[0])
    d2 = (p4[0]-p1[0])*(p4[1]-p3[1]) - (p4[1]-p1[1])*(p4[0]-p3[0])

    # If d1 and d2 have opposite signs, they intersect
