import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # Precompute maximum frequency for all ranges
    from collections import defaultdict

    # To handle queries efficiently, we can precompute a 2D array
    # freq[l][r] = maximum frequency of any element in range [l, r]
    # This will be O(n^2) which is too big for n up to 3e5

    # Instead, we can use a 2D prefix sum array
    freq = defaultdict(int)
    for i in range(n):
        cnt = defaultdict(int)
        for j in range(i, n):
            cnt[a[j]] += 1
            for k in cnt:
                if cnt[k] > freq[(i, j)]:
                    freq[(i, j)] = cnt[k]

    out_lines = []
    for _ in range(q):
        l = int(next(it)) - 1  # Convert to 0-indexed
        r = int(next(it)) - 1
        if l > r:
            out_lines.append(str(0))
        else:
            out_lines.append(str(freq[(l, r)]))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
