    c = list(map(int, input().split()))

    from collections import Counter
    freq = Counter(c)

    # Try s values from 1 to sqrt(n) + 1
    def solve_case(freq):
        min_m = float('inf')

        for s in range(1, int(n**0.5) + 2):
            total = 0

            for k in freq.values():
                if k == 0:
                    continue

                # We need to express k as a sum of s and s-1
                # Let m be the number of screens for this category
                # Then k = a*s + b*(s-1) where a, b >= 0

                # This is equivalent to: k = m*s - b, where b = number of almost filled screens
                # For a to be >= 0: k - (m*s - k) = k - m*s + k = 2k - m*s >= 0
                # So m <= 2k/s

                # And for b to be >= 0: m*s >= k
                # So m >= ceil(k/s)

                m_min = (k + s - 1) // s  # ceil(k/s)

                # Try a few values around m_min to see if it works
                for m in range(m_min, m_min + 2):
                    if m * s >= k and 2 * k - m * s >= 0:
                        total += m

            if total < min_m:
                min_m = total

        # Also try s values up to n (worse case: 1 icon per screen)
        for s in range(int(n**0.5) + 2, n + 1):
            total = 0

            for k in freq.values():
                if k == 0:
                    continue

                # If s > k, we need at least 1 screen
