def can_place(a, b, h, w, extensions, k):
    # Try to use k extensions to make a rectangle fit
    # Check both configurations: (a,b) on (h,w) or (b,a) on (h,w)

    # Sort extensions so we can try from largest to smallest
    extensions.sort(reverse=True)

    # Try all possible splits of k extensions between h and w
    for i in range(k + 1):
        j = k - i

        # Try all combinations of i extensions for h
        # and j extensions for w
        for h_comb in combinations(extensions, i):
            for w_comb in combinations(extensions, j):
                # Check if these extensions are disjoint
                if set(h_comb) & set(w_comb):
                    continue

                # Check both configurations
                for h_config, w_config in [(a, b), (b, a)]:
                    h_new = h * product(h_comb)
                    w_new = w * product(w_comb)

                    if h_new >= h_config and w_new >= w_config:
                        return True

    return False

def product(lst):
    res = 1
    for x in lst:
        res *= x
    return res

from itertools import combinations

a, b, h, w, n = map(int, input().split())
extensions = list(map(int, input().split()))

# First check if we can do it with 0 extensions
if can_place(a, b, h, w, extensions, 0):
    print(0)
else:
    # Try from 1 to n extensions
    found = -1
    for k in range(1, n + 1):
        if can_place(a, b, h, w, extensions, k):
            found = k
            break

    print(found)
