def can_meet(x, v, t):
    left = x[0] - t * v[0]
    right = x[0] + t * v[0]

    for i in range(1, len(x)):
        left = max(left, x[i] - t * v[i])
        right = min(right, x[i] + t * v[i])

    return left <= right

def find_min_time(x, v, low, high, eps=1e-9):
    while high - low > eps:
        mid1 = low + (high - low) / 3
        mid2 = high - (high - low) / 3

        if can_meet(x, v, mid1):
            high = mid2
        else:
            low = mid1

    return (low + high) / 2

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    x = list(map(int, data[1:n+1]))
    v = list(map(int, data[n+1:2*n+1]))

    # Binary search bounds
    low = 0.0
    high = 1e9

    result = find_min_time(x, v, low, high)
    print("{0:.6f}".format(result))

if __name__ == "__main__":
    main()
"}

