def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    segments = []
    types = set()
    start = 0

    for i in range(n):
        if a[i] in types:
            # We have a duplicate, form a segment from start to i
            segments.append((start + 1, i + 1))  # 1-indexed
            types = set()
            start = i + 1

        types.add(a[i])

    if start <= n:
        # We didn't finish all pearls
        return

    print(len(segments))
    for l, r in segments:
        print(l, r)

if __name__ == "__main__":
    solve()
