def solve_andrey_problem():
    n = int(input().strip())
    probabilities = list(map(float, input().split()))

    # Try all subsets of friends
    max_prob = 0.0

    # Try asking 1 friend
    for p in probabilities:
        if p > max_prob:
            max_prob = p

    # Try asking all friends
    product_of_others = 1.0
    total = 0.0
    for i in range(n):
        total += probabilities[i] * product_of_others
        product_of_others *= (1.0 - probabilities[i])
    if total > max_prob:
        max_prob = total

    # Try asking all possible subsets of size > 1
    for i in range(n):
        for j in range(i + 1, n):
            # Ask friends i and j
            prob_i = probabilities[i] * (1.0 - probabilities[j])
            prob_j = probabilities[j] * (1.0 - probabilities[i])
            total = prob_i + prob_j
            if total > max_prob:
                max_prob = total

    # Try asking all possible subsets of size 3
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # Ask friends i, j, and k
                total = 0.0
                total += probabilities[i] * (1.0 - probabilities[j]) * (1.0 - probabilities[k])
                total += probabilities[j] * (1.0 - probabilities[i]) * (1.0 - probabilities[k])
                total += probabilities[k] * (1.0 - probabilities[i]) * (1.0 - probabilities[j])
                if total > max_prob:
                    max_prob = total

    print(f"{max_prob:.12f}")

if __name__ == "__main__":
    solve_andrey_problem()
