    n = int(input().strip())
    probabilities = list(map(float, input().split()))

    max_prob = 0.0

    # Try all subsets of friends
    # For each subset, calculate probability of exactly one success
    # For subsets of size k, we need to consider all combinations

    # Try asking 1 friend
    for p in probabilities:
        if p > max_prob:
            max_prob = p

    # Try asking all friends
    total = 0.0
    product = 1.0
    for i in range(n):
        total += probabilities[i] * product
        product *= (1.0 - probabilities[i])
    if total > max_prob:
        max_prob = total

    # Try all subsets of size > 1
    from itertools import combinations
    for k in range(2, n + 1):
        for indices in combinations(range(n), k):
            # Calculate probability for this subset
            # Probability of exactly one success
            prob = 0.0
            product_of_others = 1.0
            for i, p in enumerate(probabilities):
                if i in indices:
                    # This friend is in the subset
                    prob += p * product_of_others
                    product_of_others *= (1.0 - probabilities[i])

            if prob > max_prob:
                max_prob = prob

    print(f"{max_prob:.12f}")

if __name__ == "__main__":
    solve_andrey_problem()
