    # Calculate total number of characters
    s = sum(len(string) for row in initial for string in row)

    # Find all positions where initial and final differ
    diff = []
    for i in range(n):
        for j in range(m):
            if initial[i][j] != final[i][j]:
                diff.append((i, j))

    # If no differences, just print 0
    if not diff:
        print(0)
        return

    # Strategy: move characters to a central position (0, 0) and then to target
    q = []

    # Move all characters to (0, 0)
    for i, j in diff:
        # Move to (0, 0)
        cell = (i, j)
        target = (0, 0)

        # Move to the same row if possible, or same column
        if i == 0:
            # Same row, move directly
            operations = [(i, j, i, 0) for _ in range(len(initial[i][j]))]
        elif j == 0:
            # Same column, move directly
            operations = [(i, j, 0, j) for _ in range(len(initial[i][j]))]
        else:
            # Need to move through an intermediate
            if i > 0:
                # Move to (i, 0) first
                operations += [(i, j, i, 0) for _ in range(len(initial[i][j]))]
