for k in range(1, 33):
    target = n - k * p

    # Use a greedy bitmask approach to check if we can express target as sum of k powers of two
    # We try all combinations of k powers of two up to 2^30 (since 2^30 is about 1 billion)
    found = False

    # Try all combinations of k powers of two
    # This is a bit inefficient, but we can optimize by checking bitmasks
    for mask in range(1, 1 << 31):
        if bin(mask).count('1') == k:
            power_sum = 0
            for i in range(31):
                if mask & (1 << i):
                    power_sum += 1 << i
            if power_sum == target:
                found = True
                break

    if found:
        print(k)
        exit()

